  if (m.tmax >= 30) return 'Il va faire jusqu’à ' + Math.trunc(m.tmax) + '°C : ' + (tu ? 'bois' : 'buvez') + ' beaucoup d’eau et ' + (tu ? 'évite' : 'évitez') + ' le grand soleil.';
